// ===== 1. Junta o texto de TODOS os itens de entrada =====
const partes = [];
for (let idx = 0; idx < $input.all().length; idx++) {
  const it = $input.all()[idx];
  let t = it.json.data ?? it.json.body ?? it.json.text ?? it.json.csv ?? '';

  if (!t && it.binary) {
    const key = Object.keys(it.binary)[0];
    const buf = await this.helpers.getBinaryDataBuffer(idx, key);
    t = buf.toString('utf-8');
  }
  if (typeof t === 'string' && t.trim()) partes.push(t);
}

let texto = partes.join('\n').replace(/^\uFEFF/, '');
if (!texto.trim()) throw new Error('Nenhum texto CSV encontrado na entrada.');

// ===== 2. Normaliza quebras de linha =====
if (!/[\r\n]/.test(texto)) texto = texto.replace(/\\r\\n|\\n/g, '\n');
texto = texto.replace(/\r\n/g, '\n').replace(/\r/g, '\n');

// ===== 3. Parser CSV =====
function parseCSV(str, sep = ',') {
  const rows = [];
  let row = [], field = '', aspas = false;
  for (let i = 0; i < str.length; i++) {
    const c = str[i], next = str[i + 1];
    if (aspas) {
      if (c === '"' && next === '"') { field += '"'; i++; }
      else if (c === '"') aspas = false;
      else field += c;
    } else if (c === '"') aspas = true;
    else if (c === sep) { row.push(field); field = ''; }
    else if (c === '\n') { row.push(field); field = ''; rows.push(row); row = []; }
    else field += c;
  }
  if (field !== '' || row.length) { row.push(field); rows.push(row); }
  return rows.filter(r => r.some(v => v.trim() !== ''));
}

const [cab, ...dados] = parseCSV(texto, ',');
const cols = cab.map(c => c.trim());

// ===== 4. Um único item com um array de 9 registros (índice a partir de 0) =====
const tabela = dados.map((v, i) => ({
  indice: i,
  ...Object.fromEntries(cols.map((c, j) => [c, (v[j] ?? '').trim()])),
}));

return [{ json: { tabela } }];

const IPCA_ESTIMADO = 4.5;
const ORDEM = ['conservador', 'moderado', 'arrojado'];

const EXPLICACOES = [
  { re: /selic|liquidez diaria|poupanca|reserva/, texto: 'tem baixo risco e liquidez imediata, ideal para reserva de emergência e preservação do capital' },
  { re: /ipca/, texto: 'protege o poder de compra contra a inflação e busca ganho real acima do IPCA; é indicado para prazos longos e pode oscilar antes do vencimento' },
  { re: /cdb|lci|lca|renda fixa|prefixado|debenture/, texto: 'é um investimento de renda fixa que pode contribuir para a estabilidade da carteira' },
  { re: /multimercado/, texto: 'investe em diferentes mercados, como juros, câmbio e bolsa, buscando diversificação com risco moderado' },
  { re: /fii|imobili/, texto: 'permite investir no mercado imobiliário sem comprar um imóvel diretamente, mas o valor da cota pode oscilar' },
  { re: /etf/, texto: 'oferece exposição diversificada ao mercado de ações e pode apresentar oscilações no curto prazo' },
  { re: /fundo de acoes|acoes/, texto: 'investe em uma carteira de ações e pode apresentar alta volatilidade' },
  { re: /cripto|bitcoin/, texto: 'apresenta elevada volatilidade e risco de perdas significativas' },
];

const DISCLAIMER =
  'As rentabilidades informadas são referências e não garantem resultados futuros. Esta sugestão automatizada não substitui a análise de um profissional habilitado.';

const norm = (s) =>
  String(s ?? '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim();

const toNum = (v) => {
  if (typeof v === 'number') return v;
  if (v === undefined || v === null || v === '') return NaN;

  const s = String(v).replace(/[R$\s]/g, '');
  return Number(
    s.includes(',')
      ? s.replace(/\./g, '').replace(',', '.')
      : s
  );
};

const fmt = (n) =>
  Number(n).toLocaleString('pt-BR', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });

const cap = (s) => {
  const t = String(s ?? '').trim();
  return t ? t[0].toUpperCase() + t.slice(1).toLowerCase() : t;
};

function coletar(x, teste, acc = []) {
  if (Array.isArray(x)) {
    x.forEach((i) => coletar(i, teste, acc));
  } else if (x && typeof x === 'object') {
    if (teste(x)) {
      acc.push(x);
    } else {
      Object.values(x).forEach((v) => coletar(v, teste, acc));
    }
  }
  return acc;
}

function retornoNum(r) {
  const s = String(r ?? '');
  const match = s.match(/[\d.,]+/);

  if (!match) return null;

  const n = parseFloat(match[0].replace(',', '.'));

  if (!Number.isFinite(n)) return null;

  return /ipca/i.test(s) ? n + IPCA_ESTIMADO : n;
}

// =============== LEITURA DO MERGE ===============

const entrada = $input.all().map((item) => item.json);

// O Merge contém body.clientes e tabela no mesmo objeto.
const catalogo = coletar(
  entrada,
  (o) => o.produto !== undefined && o.perfil !== undefined
).map((p) => ({
  perfil: norm(p.perfil),
  produto: p.produto,
  minimo: toNum(p.minimo),
  rentabilidade: p.rentabilidade,
  retorno: retornoNum(p.rentabilidade),
}));

const clientes = coletar(
  entrada,
  (o) =>
    o.produto === undefined &&
    o.perfil !== undefined &&
    o.nome !== undefined
);

if (!catalogo.length) {
  throw new Error(
    'Catálogo não encontrado. Verifique o campo tabela no output do Merge.'
  );
}

if (!clientes.length) {
  throw new Error(
    'Clientes não encontrados. Verifique o campo body.clientes no output do Merge.'
  );
}

// =============== SELEÇÃO DOS PRODUTOS ===============

function explicar(p, alvo, perfilLabel, valor) {
  const explicacao =
    EXPLICACOES.find((e) => e.re.test(norm(p.produto)))?.texto ??
    'é uma opção disponível no catálogo para análise';

  const encaixe =
    p.pi === alvo
      ? `Está classificado para o perfil ${perfilLabel}.`
      : 'É uma alternativa de perfil mais conservador, que pode contribuir para a diversificação.';

  const aporte = Number.isFinite(p.minimo)
    ? `O aporte mínimo informado é de R$ ${fmt(p.minimo)}${
        Number.isFinite(valor)
          ? `, dentro do saldo disponível de R$ ${fmt(valor)}`
          : ''
      }.`
    : '';

  const rent = p.rentabilidade
    ? `Rentabilidade informada no catálogo: ${p.rentabilidade}.`
    : '';

  return `${p.produto}: ${explicacao}. ${encaixe} ${aporte} ${rent}`
    .replace(/\s+/g, ' ')
    .trim();
}

function sugerir(perfil, valor) {
  const idx = ORDEM.indexOf(norm(perfil));
  const alvo = idx === -1 ? 1 : idx;
  const perfilLabel = cap(idx === -1 ? 'moderado' : perfil);

  const elegiveis = catalogo
    .map((p) => ({ ...p, pi: ORDEM.indexOf(p.perfil) }))
    .filter((p) => p.pi !== -1 && p.pi <= alvo)
    .filter(
      (p) =>
        !Number.isFinite(valor) ||
        !Number.isFinite(p.minimo) ||
        p.minimo <= valor
    );

  elegiveis.sort((a, b) => {
    const distA = alvo - a.pi;
    const distB = alvo - b.pi;

    if (distA !== distB) return distA - distB;

    // Produtos com rentabilidade variável ficam por último.
    return (b.retorno ?? -1) - (a.retorno ?? -1);
  });

  return elegiveis.slice(0, 3).map((p, i) => ({
    posicao: i + 1,
    produto: p.produto,
    perfil_produto: p.perfil,
    minimo: Number.isFinite(p.minimo) ? p.minimo : null,
    rentabilidade: p.rentabilidade ?? null,
    explicacao: explicar(p, alvo, perfilLabel, valor),
  }));
}

// =============== SAÍDA PARA A LLM ===============

return clientes.map((c) => {
  const valor = toNum(c.saldo);
  const perfilValido = ORDEM.includes(norm(c.perfil));
  const perfilLabel = cap(perfilValido ? c.perfil : 'moderado');
  const sugestoes = sugerir(c.perfil, valor);

  const contexto = {
    nome: c.nome,
    email: c.email ?? '',
    perfil: perfilLabel,
    saldo: Number.isFinite(valor) ? fmt(valor) : null,
    melhor_escolha: sugestoes[0] ?? null,
    outras_opcoes: sugestoes.slice(1),
    quantidade_sugestoes: sugestoes.length,
    aviso:
      sugestoes.length < 3
        ? 'Menos de 3 produtos elegíveis para este perfil e saldo.'
        : null,
    disclaimer: DISCLAIMER,
  };

  return {
    json: {
      nome: c.nome,
      email: c.email ?? '',
      perfil: perfilLabel,
      saldo: Number.isFinite(valor) ? valor : null,

      sugestoes,
      melhor_escolha: sugestoes[0]?.produto ?? null,
      sugestao_1: sugestoes[0]?.produto ?? null,
      sugestao_2: sugestoes[1]?.produto ?? null,
      sugestao_3: sugestoes[2]?.produto ?? null,

      quantidade_sugestoes: sugestoes.length,
      aviso: contexto.aviso,

      // O próximo node de IA utilizará este contexto.
      contexto_llm: JSON.stringify(contexto),

      // A mensagem será escrita pela LLM no próximo node.
      mensagem: null,
    },
  };
});

const items = $input.all();

const normalizados = items.map((item) => {
  const dados = item.json;

  // Converte números e valores monetários para um formato consistente.
  function converterNumero(valor) {
    if (valor === null || valor === undefined || valor === '') {
      return null;
    }

    if (typeof valor === 'number') {
      return Number.isFinite(valor) ? valor : null;
    }

    const texto = String(valor).trim().replace(/[R$\s]/g, '');
    const numero = Number(
      texto.includes(',')
        ? texto.replace(/\./g, '').replace(',', '.')
        : texto
    );

    return Number.isFinite(numero) ? numero : null;
  }

  function formatarMoeda(valor) {
    const numero = converterNumero(valor);

    if (numero === null) return 'Não informado';

    return numero.toLocaleString('pt-BR', {
      style: 'currency',
      currency: 'BRL',
    });
  }

  function textoSeguro(valor, padrao = '') {
    if (valor === null || valor === undefined) return padrao;
    return String(valor).trim() || padrao;
  }

  // Normaliza as sugestões, preservando os detalhes de cada produto.
  let sugestoes = Array.isArray(dados.sugestoes)
    ? dados.sugestoes
    : [];

  sugestoes = sugestoes
    .filter((s) => s && typeof s === 'object' && s.produto)
    .map((s, indice) => ({
      posicao: Number(s.posicao) || indice + 1,
      produto: textoSeguro(s.produto),
      perfil_produto: textoSeguro(s.perfil_produto, 'Não informado'),
      minimo: converterNumero(s.minimo),
      minimo_formatado:
        converterNumero(s.minimo) !== null
          ? formatarMoeda(s.minimo)
          : 'Não informado',
      rentabilidade: textoSeguro(
        s.rentabilidade,
        'Não informada'
      ),
      explicacao: textoSeguro(
        s.explicacao,
        'Consulte as características do produto antes de investir.'
      ),
    }));

  // Identifica a primeira sugestão como escolha prioritária.
  const melhorEscolha =
    sugestoes.find((s) => s.posicao === 1) || sugestoes[0] || null;

  const alternativas = sugestoes.filter(
    (s) => s.produto !== melhorEscolha?.produto
  );

  const nome = textoSeguro(dados.nome, 'Cliente');
  const email = textoSeguro(dados.email).toLowerCase();
  const perfil = textoSeguro(dados.perfil, 'Não informado');
  const saldo = converterNumero(dados.saldo);

  const aviso = textoSeguro(
    dados.aviso,
    sugestoes.length < 3
      ? 'Foram encontradas menos de três opções elegíveis.'
      : ''
  );

  const contexto = {
    nome,
    primeiro_nome: nome.split(/\s+/)[0],
    email,
    perfil,
    saldo: saldo,
    saldo_formatado: formatarMoeda(saldo),
    quantidade_sugestoes: sugestoes.length,
    melhor_escolha: melhorEscolha,
    alternativas,
    aviso,
    disclaimer: textoSeguro(
      dados.disclaimer,
      'Rentabilidades informadas são referências e não garantem resultados futuros. Esta sugestão automatizada não substitui a análise de um profissional habilitado.'
    ),
  };

  // Texto organizado para ser enviado ao node OpenAI.
  const contextoOpenAI = [
    `Nome: ${contexto.nome}`,
    `Primeiro nome: ${contexto.primeiro_nome}`,
    `E-mail: ${contexto.email}`,
    `Perfil de investidor: ${contexto.perfil}`,
    `Saldo disponível: ${contexto.saldo_formatado}`,
    '',
    'MELHOR ESCOLHA:',
    melhorEscolha
      ? JSON.stringify(melhorEscolha, null, 2)
      : 'Nenhuma opção elegível foi encontrada.',
    '',
    `Aviso obrigatório: ${contexto.disclaimer}`,
  ]
    .filter((linha) => linha !== null && linha !== undefined)
    .join('\n');

  return {
    json: {
      nome: contexto.nome,
      primeiro_nome: contexto.primeiro_nome,
      email: contexto.email,
      perfil: contexto.perfil,
      saldo: contexto.saldo,
      saldo_formatado: contexto.saldo_formatado,
      melhor_escolha_detalhes: melhorEscolha,
      sugestoes,
      disclaimer: contexto.disclaimer,
      contexto_openai: contextoOpenAI,

      // Controle para impedir envio sem destinatário ou recomendação.
      pronto_para_gerar:
        Boolean(contexto.email) && Boolean(melhorEscolha),
    },
  };
});

return normalizados;

const items = $input.all();

// IMPORTANTE: troque "Code node 2" pelo nome exato
// do node anterior ao OpenAI que contém os dados dos clientes.
const clientes = $('Code in JavaScript').all();

function interpretarResposta(item) {
  const dados = item.json;

  // Caminho encontrado no output real do seu OpenAI
  const texto = dados.output?.[0]?.content?.find(
    c => c.type === 'output_text'
  )?.text;

  if (!texto) {
    throw new Error(
      'Resposta de texto não encontrada no item do OpenAI.'
    );
  }

  // Converte o JSON textual da IA em objeto JavaScript
  let resposta;

  try {
    resposta = JSON.parse(texto);
  } catch (erro) {
    throw new Error(
      `A resposta da IA não contém JSON válido. Item: ${JSON.stringify(dados)}`
    );
  }

  return resposta;
}

return items.map((item, index) => {
  const respostaIA = interpretarResposta(item);

  // Recupera os dados originais do cliente
  const cliente = clientes[index]?.json ?? {};

  const email = cliente.email ?? '';
  const nome = cliente.nome ?? '';
  const primeiroNome =
    cliente.primeiro_nome ??
    nome.trim().split(/\s+/)[0] ??
    '';

  const assunto = String(respostaIA.assunto ?? '').trim();
  const mensagem = String(respostaIA.mensagem ?? '').trim();

  const erros = [];

  if (!email) erros.push('E-mail do cliente não encontrado.');
  if (!assunto) erros.push('Assunto não encontrado.');
  if (!mensagem) erros.push('Mensagem não encontrada.');

  return {
    json: {
      ...cliente,

      // Dados gerados pelo OpenAI
      assunto,
      mensagem,

      // Campos para o node de envio
      email,
      nome,
      primeiro_nome: primeiroNome,

      pronto_para_enviar: erros.length === 0,
      erro_normalizacao: erros.length
        ? erros.join(' ')
        : null
    }
  };
});
